/// Pitch class of the root, 0 = C.
pub root: usize,
pub quality: Quality,
/// Cosine against the template, 0..≈1. Not a probability.
pub score: f32,

/// Which lane it was played on, so the panel can group it the way the
/// spectrogram is grouped.
pub lane: Lane,
/// What the game calls this sound. A group name such as `laser_fire`, or
/// a track title. Free text on purpose.
pub name: String,
/// Which of the group's interchangeable files was chosen, such as `opt03`.
/// None when the sound has no variants, or was synthesised rather than
/// loaded.
pub variant: Option<String>,
/// The file it came from, when it came from one. Lets the panel put the
/// event beside its entry in the library.
pub path: Option<PathBuf>,
/// How long the source said it runs. None means the source did not say,
/// not that it is instantaneous.
pub duration: Option<Duration>,
/// The gain the game applied, before any distance attenuation.
pub gain: f32,
/// Distance attenuation, one for a sound at the camera and zero for one
/// too far to hear. One for sounds that are not positioned at all.
pub spatial: f32,
/// Whether starting this retires the other voices on its lane. True for
/// the music track and for the single conversation voice, both of which
/// are one sink that a new sound takes over rather than joins.
pub exclusive: bool,
/// When the game started it.
pub at: Instant,
/// Monotonic, process-wide. Gives the panel a stable sort for events that
/// share an instant, and lets a reader tell a repeat from a redraw.
pub seq: u64,

/// The start that began it.
pub event: SoundEvent,
/// When it is expected to finish.
pub ends: Instant,
/// Whether `ends` came from the source or from `UNKNOWN_VOICE_LIFE`.
/// 
/// The panel must show this. A guessed end drawn as a measured one turns
/// the display into a claim the engine cannot support.
pub end_is_guessed: bool,

pub path: std::path::PathBuf,
/// File stem, e.g. "opt03".
pub name: String,
/// Path from the scanned root down to the containing directory, slash-joined,
/// e.g. "combat/laser_fire". Empty for a file sitting directly in the root.
pub group: String,
/// First path component of `group`, e.g. "combat". Empty if `group` is empty.
pub category: String,
pub ext: String,
pub bytes: u64,

/// The one music sink: the track the game is playing.
Music = 0,
/// Every sound effect voice, already summed by the lane's own mixer.
Sfx = 1,

/// Pitch class of the root, 0 = C.
pub root: usize,
pub quality: Quality,
/// Cosine against the template, 0..≈1. Not a probability.
pub score: f32,

/// Which lane it was played on, so the panel can group it the way the
/// spectrogram is grouped.
pub lane: Lane,
/// What the game calls this sound. A group name such as `laser_fire`, or
/// a track title. Free text on purpose.
pub name: String,
/// Which of the group's interchangeable files was chosen, such as `opt03`.
/// None when the sound has no variants, or was synthesised rather than
/// loaded.
pub variant: Option<String>,
/// The file it came from, when it came from one. Lets the panel put the
/// event beside its entry in the library.
pub path: Option<PathBuf>,
/// How long the source said it runs. None means the source did not say,
/// not that it is instantaneous.
pub duration: Option<Duration>,
/// The gain the game applied, before any distance attenuation.
pub gain: f32,
/// Distance attenuation, one for a sound at the camera and zero for one
/// too far to hear. One for sounds that are not positioned at all.
pub spatial: f32,
/// Whether starting this retires the other voices on its lane. True for
/// the music track and for the single conversation voice, both of which
/// are one sink that a new sound takes over rather than joins.
pub exclusive: bool,
/// When the game started it.
pub at: Instant,
/// Monotonic, process-wide. Gives the panel a stable sort for events that
/// share an instant, and lets a reader tell a repeat from a redraw.
pub seq: u64,

/// The start that began it.
pub event: SoundEvent,
/// When it is expected to finish.
pub ends: Instant,
/// Whether `ends` came from the source or from `UNKNOWN_VOICE_LIFE`.
/// 
/// The panel must show this. A guessed end drawn as a measured one turns
/// the display into a claim the engine cannot support.
pub end_is_guessed: bool,

pub path: std::path::PathBuf,
/// File stem, e.g. "opt03".
pub name: String,
/// Path from the scanned root down to the containing directory, slash-joined,
/// e.g. "combat/laser_fire". Empty for a file sitting directly in the root.
pub group: String,
/// First path component of `group`, e.g. "combat". Empty if `group` is empty.
pub category: String,
pub ext: String,
pub bytes: u64,

/// The one music sink: the track the game is playing.
Music = 0,
/// Every sound effect voice, already summed by the lane's own mixer.
Sfx = 1,

/// The name the store writes and the code names. Dotted, stable, never
/// shown to a person. Renaming one silently orphans anybody's override of
/// it, which is the cost of it being the identity.
pub id: &'static str,
/// What the panel calls it.
pub name: &'static str,
/// The section it is listed under, and the colour class of its keycap.
pub group: &'static str,
/// When this action can fire at all. Empty means always.
/// 
/// Two actions in different contexts may share a chord without it being a
/// conflict. That is not a nicety: a real scheme has W panning the camera
/// and W being thrust while piloting, and those are two actions on one key
/// on purpose. Without this field the panel would open reporting the
/// scheme's own defaults as broken, which teaches people to ignore the
/// conflict marker — and then it is worth nothing when a conflict is real.
/// 
/// The engine takes the application's word for it. `held` and `pressed` do
/// not consult this; the application already gates those call sites, and a
/// context the engine enforced would be a second, disagreeing copy of that
/// gate. This says only "these two are never live at once".
pub context: &'static str,
/// One line under the name, when there is something worth saying.
pub hint: &'static str,
/// What it is bound to before anybody changes anything.
pub defaults: &'static [Chord],

pub actions: Vec<ActionWire>,
/// Sorted by id, so a snapshot resent for an unrelated reason is the same
/// bytes as the last one and a diff of the channel means something.
pub overrides: Vec<(String, Vec<Chord>)>,

pub id: EntityId,
/// The generation the row was drawn from. Resolved the same way a request
/// is, and refused the same way when it has aged out — a stale index
/// writing into a fresh table sets a parameter on the wrong thing.
pub generation: u64,
/// Index into that row's `params`.
pub param: u16,
pub value: Value,

/// Nothing to go to. Category headers and grouping rows.
None,
/// It has a position in the world. The camera can fly to it.
World,
/// It has a rect on the screen. Going to it means showing it.
Screen,

/// Plural, and shown as the category header: "Planets", "Stations".
pub name: String,
/// The dot beside every row of this kind.
pub color: [u8; 3],
/// What clicking a row of this kind can do.
pub focus: Focus,

pub id: EntityId,
/// Index into `Census::kinds`. Out of range draws unstyled rather than
/// panicking — a census is data from another crate, not an invariant.
pub kind: u16,
/// `ROOT` for a top-level row. A parent that is not in `rows` orphans the
/// row, and the panel draws it at the top level rather than dropping it.
pub parent: EntityId,
pub name: String,
/// The right-hand column: a position, a count, a state. Short. The panel
/// clips it before it clips the name.
pub detail: String,
pub flags: u8,
/// How many children exist, whether or not any were sent. A closed
/// category is one row that can still say how much is behind it.
/// 
/// Params are NOT counted here. The count answers "how much is behind
/// this heading", and a person reading "Sand 5" wants that to mean five
/// things and not five knobs on one thing.
pub children: u32,
/// The values this row exposes, in the order they should be drawn.
/// 
/// Filled only for rows the panel has open — see the banner. A row with
/// params is EXPANDABLE like one with children, and the two mix: params
/// are drawn first, then child rows.
pub params: Vec<Param>,

/// Make it the selection, and nothing else.
Select,
/// Make it the selection and go there — fly the camera, open the panel.
Focus,
/// Add to or remove from the selection. Ctrl-click.
Extend,
/// Show it or hide it, for a kind where that means something.
Toggle,

pub id: EntityId,
/// The generation the row was drawn from. See the banner: the publisher
/// resolves against this table, not the current one.
pub generation: u64,
pub action: Action,

/// Bumped by `publish`. A request carries the generation it was drawn
/// from, and the publisher resolves against that one.
pub generation: u64,
pub kinds: Vec<Kind>,
/// Any order. The panel builds the tree from `parent`, and draws rows of
/// one parent in the order they appear here.
pub rows: Vec<Entity>,
/// Why this snapshot is not everything, when it is not.
/// 
/// A publisher that caps a category at a thousand rows says so here, and
/// the panel puts it under the tree. A cap nobody is told about reads as
/// "that is all there is", which is the one thing a census must not say
/// by accident.
pub note: String,

Bool(bool),
/// Whole numbers: counts, columns, indices.
Int(i64),
Float(f32),
/// Straight RGBA, unmultiplied. The panel draws a swatch and a picker.
Color([u8; 4]),
Text(String),
/// A size or a position, edited as two fields on one row.
Vec2([f32; 2]),

/// Short. It shares a row with its editor, so it is a label and not a
/// sentence — "Count", "Drift", "Grid columns".
pub name: String,
pub value: Value,
/// Inclusive bounds for `Int`, `Float` and `Vec2`. `None` draws a drag
/// field with no stops, which is right for a value with no natural range
/// and wrong for one that has one — a particle count dragged to negative
/// is a publisher's crash, not a person's mistake.
pub range: Option<[f32; 2]>,
/// A suffix for the readout: "px", "/s", "°". Empty for a bare number.
pub unit: String,
/// Drawn, and not editable. For a value the publisher computes and wants
/// SEEN — a measured width, a live count — beside the ones it accepts
/// back. Greyed rather than hidden: the number is the point.
pub readonly: bool,
/// The heading this value belongs under: "Transform", "Material", "Audio".
/// 
/// Empty for a value that belongs to the object at large, which is what a
/// publisher that has never heard of this field sends. The Inspector draws
/// those first, under no heading, and every named group after them in the
/// order the params arrive — so grouping is opt-in and ordering is the
/// publisher's, not this file's.
pub group: String,

/// The CRT pass writes here in embedded mode.
pub view: wgpu::TextureView,
/// Texture size in pixels. The panel scales it to fit a rect.
pub size: (u32, u32),

/// The panel's own shape, whatever it is. The game is told to render at
/// exactly this size, so its UI lays itself out against the real estate it
/// actually has and the image arrives at 1:1 with no resample at all.
/// 
/// The one case this cannot deliver is an image whose renderer takes no
/// instruction: the editor's own scene, which is sized by the editor's
/// window. There `resolve_fixed_source` turns this back into the render
/// aspect and it letterboxes.
Native,
/// Fit this width:height, centred, with the remainder left to the panel
/// background — and render at exactly the rect that fits.
/// 
/// This is composing against a fixed frame: what you ship at holds still
/// while the panel moves around it. It is a letterbox and never a scale,
/// for the same reason Native is not — the letterboxed rect is the size
/// that goes out on the wire.
Ratio(f32, f32),

/// Source image size. The Shader Lab drives this field by name.
pub resolution: [f32; 2],
/// Seconds. Driven by name in the Shader Lab, written at `TIME_OFFSET`.
pub time: f32,
/// Destination width in pixels — what `in.position.x` counts.
pub output_w: f32,
/// Destination height in pixels — what `in.position.y` counts.
pub output_h: f32,
/// Horizontal bow of the glass.
pub curve_x: f32,
/// Vertical bow. Zero is a cylindrical tube — a Trinitron is curved
/// horizontally and dead flat vertically, and one scalar cannot say so.
pub curve_y: f32,
/// Rounded corner radius, in DESTINATION pixels.
pub corner_radius: f32,
/// Glass thickness, in units of half the screen width.
pub glass_thickness: f32,
/// Refractive index of the faceplate. Soda-lime glass is about 1.52.
pub glass_ior: f32,
/// Mask-to-phosphor spacing, same units as `glass_thickness`.
pub mask_gap: f32,
/// Virtual viewer position, screen widths from centre.
pub eye_x: f32,
pub eye_y: f32,
/// Viewer distance. Larger is more orthographic and flattens the parallax.
pub eye_dist: f32,
/// Master scale on the parallax offset. Zero pins the mask to the image.
pub parallax_strength: f32,
/// Master scale over the whole convergence block. The legacy name: it was
/// a fixed horizontal RGB split and is now the gain on a real one.
pub aberration_amount: f32,
pub conv_r_x: f32,
pub conv_r_y: f32,
pub conv_b_x: f32,
pub conv_b_y: f32,
/// Radial divergence — the bow that grows toward the corners.
pub conv_radial_r: f32,
pub conv_radial_b: f32,
/// 0 none, 1 aperture grille, 2 shadow mask, 3 slot mask, 4 Trinitron.
pub mask_type: f32,
/// Destination pixels per full RGB triad, measured at screen centre.
pub mask_triad_px: f32,
pub mask_strength: f32,
/// Brightness compensation. A mask eats most of the light and a real tube
/// was driven harder to answer it.
pub mask_boost: f32,
/// Slot mask only: vertical slot period in destination pixels.
pub slot_height_px: f32,
/// Trinitron only: how many damper wires cross the screen.
pub damper_count: f32,
pub damper_strength: f32,
/// How much the mask parallax biases each channel's aperture separately.
pub parallax_coupling: f32,
/// Lines across the tube. 240 is an arcade signal, 480 a broadcast field.
pub scanline_count: f32,
pub scanline_intensity: f32,
/// Beam width as a fraction of the line pitch.
pub scanline_thickness: f32,
/// How much a bright beam widens. This is what keeps highlights from
/// being cut in half by their own scanline.
pub beam_bloom: f32,
/// Non-zero alternates the field every frame.
pub interlace: f32,
pub vignette_intensity: f32,
pub flicker_intensity: f32,
pub jitter_intensity: f32,
pub hsync_intensity: f32,
pub grain_intensity: f32,
pub grain_size: f32,
pub grain_speed: f32,
pub grain_color: f32,
/// 0 off, 1 warp grid, 2 displacement, 3 convergence, 4 mask only,
/// 5 magnifier.
pub viz_mode: f32,
/// Loupe centre, in normalized destination coordinates.
pub viz_probe_x: f32,
pub viz_probe_y: f32,
pub viz_zoom: f32,
pub viz_grid_div: f32,
/// Zero leaves the continuous mask alone and costs nothing.
pub phosphor_on: f32,
/// How many RGB triads fit across the screen. A COUNT, not a pitch:
/// "how many are there" is the question a person actually asks, and a
/// pitch in pixels answers it only after dividing.
pub phosphor_triads_x: f32,
/// How many phosphor rows fit down the screen.
pub phosphor_rows: f32,
/// The black matrix: the fraction of a cell that is the gap around it.
pub phosphor_gap: f32,
/// Beam spot radius, in cells. This is the "average of nearby cells" —
/// at 1.0 a cell sees roughly its own area, above that it sees its
/// neighbours and the picture softens the way a defocused gun does.
pub phosphor_beam: f32,
/// Cell shape, 0 rectangular through 1 elliptical.
pub phosphor_round: f32,
/// How much a lit cell spills into the dark matrix around it.
pub phosphor_bleed: f32,
pub ph_r_r: f32,
pub ph_r_g: f32,
pub ph_r_b: f32,
pub ph_g_r: f32,
pub ph_g_g: f32,
pub ph_g_b: f32,
pub ph_b_r: f32,
pub ph_b_g: f32,
pub ph_b_b: f32,
/// How much the GUI is spared the phosphor grid, 0 none through 1 whole.
/// 
/// A tube shows a picture. A menu is not a picture, and a person reading
/// a settings form through a phosphor grid is reading it through a
/// four-pixel comb. The two want opposite things from the same pass.
/// 
/// The mask that separates them costs nothing to carry: the LDR image's
/// ALPHA is unused by every pass that writes it, so the tonemap, the two
/// depth-of-field passes and the FXAA pass all write zero there, egui's
/// blend accumulates alpha wherever it draws, and what arrives at this
/// pass is exactly GUI coverage. No extra target, no second pass, no
/// stencil.
pub gui_exempt: f32,
/// The GUI's share of the raster, the mask and the grain, on the same
/// 0-to-1 scale as `gui_exempt` above and read off the same alpha.
/// 
/// WHY THERE IS NO EXEMPTION FOR THE GEOMETRY
/// 
/// The warp, the convergence and the parallax decide WHERE this pass
/// samples, and the GUI has already been composited into the image being
/// sampled. Sparing the chrome the curvature would mean reading it from
/// an unwarped position while reading the scene from a warped one, out of
/// one texture, in one tap. There is no such read. Every effect that can
/// be exempted is one that multiplies AFTER the sample, and these are all
/// of them.
pub gui_exempt_scan: f32,
pub gui_exempt_mask: f32,
pub gui_exempt_grain: f32,
/// How hard a phosphor cell's edge is, 0 analytic through 1 square.
/// 
/// The analytic width is one destination pixel, which is correct and is
/// not always what somebody wants. A cell at the default density is under
/// three pixels across, so a correct one-pixel edge is a third of the
/// cell and the grid reads as soft. This scales that width down toward
/// nothing, trading aliasing for a hard edge — which is the right trade
/// when the whole reason the grid is on is to be looked at.
pub phosphor_sharp: f32,
/// Output gain, applied AFTER the mask and the cells.
/// 
/// After, and not before, because the aperture is what took the light.
/// A drive in front of it would push more of the picture into the
/// ceiling and give back nothing.
pub pic_brightness: f32,
/// Contrast around mid grey. One leaves the picture alone.
pub pic_contrast: f32,
/// The exponent on the graded picture. Below one lifts the mid tones.
pub pic_gamma: f32,
/// Where the output ceiling starts to compress, 0 through 1.
/// 
/// One is the hard clamp this pass used to end on. Below one the top of
/// the range rolls off instead of truncating, which is what gives a
/// clipped cell somewhere to go. It is also what makes `pic_brightness`
/// do anything at all, because a cell already pinned at one cannot be
/// multiplied any higher.
pub pic_knee: f32,
pub _pad0: f32,
pub _pad1: f32,
pub _pad2: f32,

pub rect: wgpu::RenderPipeline,
pub rect_surface: wgpu::RenderPipeline,
pub line: wgpu::RenderPipeline,
pub line_surface: wgpu::RenderPipeline,
pub circle: wgpu::RenderPipeline,
pub circle_surface: wgpu::RenderPipeline,
pub dust: wgpu::RenderPipeline,
pub image: wgpu::RenderPipeline,
/// Clones of `image` (same shaders/layout). One pipeline per mega-atlas
/// draw: wgpu's GL backend can hold texture bindings stale across
/// same-pipeline draws that only swap bind group 1; a pipeline switch
/// forces the rebind. Environment uses `image`, Resources+overlay use
/// `image_res`, Structures uses `image_str`.
pub image_res: wgpu::RenderPipeline,
pub image_str: wgpu::RenderPipeline,
/// One pipeline per registered layer, in registry order.
/// 
/// Empty where the application registered nothing, which is every editor
/// that opened no project. The pass walks the registry and this list
/// together, so a short list draws no registered row rather than panicking.
pub registered: Vec<wgpu::RenderPipeline>,

pub input_view: wgpu::TextureView,
pub enabled: bool,
/// Shutter fraction. The full smear is one frame of camera travel at 1.0.
pub intensity: f32,
/// The hard pixel ceiling on the smear length. It also caps a camera cut.
pub max_px: f32,
/// Sample taps along the smear vector.
pub samples: f32,

/// wgpu device + queue created, surface configured.
GpuReady,
/// All render pipelines compiled.
PipelinesReady,
/// Beginning the scene texture array upload. total = image count.
SceneTexturesStart { total: u32 },
/// N textures uploaded so far (push after each texture upload).
SceneTextureProgress { loaded: u32, total: u32, name: &'static str },
/// Every scene texture is uploaded and the bind group is built.
SceneTexturesComplete,
/// Starting a mega-atlas. id is the atlas slot number.
MegaAtlasStart {
    id:            u8,
    name:          &'static str,
    total_entries: u32,
    total_layers:  u32,
},
/// Per-layer progress within a mega-atlas.
MegaAtlasProgress { id: u8, name: &'static str, loaded: u32, total: u32 },
/// Mega-atlas fully uploaded and bind group finalized.
MegaAtlasComplete { id: u8, name: &'static str },
/// Starting ship atlas upload. total = image count.
ShipAtlasStart { total: u32 },
/// Per-image progress for ship atlas.
ShipAtlasProgress { loaded: u32, total: u32, name: &'static str },
/// Ship atlas fully uploaded.
ShipAtlasComplete,
/// Legacy subsystem initialization started.
LegacyStart,
/// Legacy atlases fully uploaded.
LegacyComplete,
/// All heavy GPU assets loaded. LoadingTerminalState transitions to Splash.
AllTexturesComplete,
/// The loader thread stopped and no assets are coming.
/// 
/// Nothing else says this. The loader owns the sending half of a channel,
/// so a thread that dies drops that half, and the render thread then reads
/// Disconnected on each frame forever. Without this event a dead loader
/// and a slow one look the same: a progress bar that does not move.
/// 
/// `reason` carries the panic message where one exists. A boot that ends
/// here must say so on the terminal, because the alternative is a person
/// waiting on a load that already failed.
LoaderFailed { reason: String },

/// wgpu device + queue created, surface configured.
GpuReady,
/// All render pipelines compiled.
PipelinesReady,
/// Beginning the scene texture array upload. total = image count.
SceneTexturesStart { total: u32 },
/// N textures uploaded so far (push after each texture upload).
SceneTextureProgress { loaded: u32, total: u32, name: &'static str },
/// Every scene texture is uploaded and the bind group is built.
SceneTexturesComplete,
/// Starting a mega-atlas. id is the atlas slot number.
MegaAtlasStart {
    id:            u8,
    name:          &'static str,
    total_entries: u32,
    total_layers:  u32,
},
/// Per-layer progress within a mega-atlas.
MegaAtlasProgress { id: u8, name: &'static str, loaded: u32, total: u32 },
/// Mega-atlas fully uploaded and bind group finalized.
MegaAtlasComplete { id: u8, name: &'static str },
/// Starting ship atlas upload. total = image count.
ShipAtlasStart { total: u32 },
/// Per-image progress for ship atlas.
ShipAtlasProgress { loaded: u32, total: u32, name: &'static str },
/// Ship atlas fully uploaded.
ShipAtlasComplete,
/// Legacy subsystem initialization started.
LegacyStart,
/// Legacy atlases fully uploaded.
LegacyComplete,
/// All heavy GPU assets loaded. LoadingTerminalState transitions to Splash.
AllTexturesComplete,
/// The loader thread stopped and no assets are coming.
/// 
/// Nothing else says this. The loader owns the sending half of a channel,
/// so a thread that dies drops that half, and the render thread then reads
/// Disconnected on each frame forever. Without this event a dead loader
/// and a slow one look the same: a progress bar that does not move.
/// 
/// `reason` carries the panic message where one exists. A boot that ends
/// here must say so on the terminal, because the alternative is a person
/// waiting on a load that already failed.
LoaderFailed { reason: String },

/// The CRT pass writes here in embedded mode.
pub view: wgpu::TextureView,
/// Texture size in pixels. The panel scales it to fit a rect.
pub size: (u32, u32),

/// The panel's own shape, whatever it is. The game is told to render at
/// exactly this size, so its UI lays itself out against the real estate it
/// actually has and the image arrives at 1:1 with no resample at all.
/// 
/// The one case this cannot deliver is an image whose renderer takes no
/// instruction: the editor's own scene, which is sized by the editor's
/// window. There `resolve_fixed_source` turns this back into the render
/// aspect and it letterboxes.
Native,
/// Fit this width:height, centred, with the remainder left to the panel
/// background — and render at exactly the rect that fits.
/// 
/// This is composing against a fixed frame: what you ship at holds still
/// while the panel moves around it. It is a letterbox and never a scale,
/// for the same reason Native is not — the letterboxed rect is the size
/// that goes out on the wire.
Ratio(f32, f32),

/// Left edge, in texture pixels from the left of the texture.
pub x: u32,
/// Top edge, in texture pixels from the top of the texture.
pub y: u32,
/// Width in texture pixels.
pub w: u32,
/// Height in texture pixels.
pub h: u32,

/// The rectangle that was actually read, after the clamp. It can be
/// smaller than the rectangle that was asked for, or moved inwards.
pub region: Region,
/// The size of the texture the region was cut from.
pub tex_size: (u32, u32),
/// The generation of the game view at the moment of the copy. A change
/// means the texture was rebuilt, so the region means a different part of
/// a different picture.
pub generation: u64,
/// Monotonic count of frames served, so a consumer can tell a repeat from
/// a fresh one.
pub frame: u64,
/// The pixels, row major, `region.w` by `region.h`.
pub image: ColorImage,

/// A uniform buffer of exactly this many bytes.
Uniform { binding: u32, size: u64 },
/// A sampled texture. `channel` picks which of the lab's images.
Texture { binding: u32, channel: usize },
/// A filtering sampler.
Sampler { binding: u32 },

/// Identifies the PIPELINE. While this is unchanged the lab reuses what
/// it built, so a slider being dragged costs a buffer write and nothing
/// else. The panel derives it from the file's revision and the chosen
/// entry points — not from the uniform values, which change every frame.
pub key: u64,
/// The composed WGSL, prelude already in front of it.
pub source: String,
pub vertex_entry: String,
pub fragment_entry: String,
/// Colour attachments the fragment stage writes.
pub targets: usize,
/// Group 0's resources. Other groups are not supported and the panel does
/// not offer a shader that uses them.
pub bindings: Vec<LabBinding>,
/// Bytes for each uniform binding, in the order the bindings list them.
pub uniforms: Vec<Vec<u8>>,
/// Preview size in pixels, before clamping to `MAX_EDGE`.
pub size: (u32, u32),

/// Built, and how long it took in milliseconds.
Compiled { millis: u32 },
/// wgpu refused it. The message is the device error, verbatim.
