/// This process — the editor's own chrome, egui and all.
Editor,
/// The child process the editor launched, measured in the child.
Game,

pub name: &'static str,
/// 0 for a span opened at the top of the frame.
pub depth: u16,
/// Nanoseconds from the start of the frame.
pub start_ns: u32,
/// Nanoseconds from the start of the frame. Never less than `start_ns`.
pub end_ns: u32,

pub spans: Vec<Span>,
/// Wall time from the first span of the frame to `frame()`, in ns.
pub total_ns: u32,
/// Spans lost to `MAX_SPANS`. Non-zero means this frame is incomplete and
/// the panel says so rather than drawing a short tree as a cheap frame.
pub dropped: u32,

/// Frames folded into this window.
pub frames: u32,
/// Wall time the window covered, in milliseconds.
pub span_ms: f32,
/// The most expensive frame in the window, in pre-order. Empty when the
/// window caught no spans.
pub worst: Vec<Bar>,
/// The instrumented work of that frame, in milliseconds. Its top-level
/// spans added up, which is what the flame chart's bars come to.
pub worst_ms: f32,
/// The wall clock that frame occupied, in milliseconds — the period from
/// one frame to the next, gate and all.
/// 
/// Carried beside the work rather than instead of it, for the reason the
/// Performance panel gives: under the budget the two differ by slack the
/// presentation gate is holding, and a panel showing only one of them
/// cannot tell a cheap frame from a late one.
pub worst_period_ms: f32,
/// Every name seen, most self time first.
pub rows: Vec<Row>,
/// Rows past `MAX_ROWS` that were dropped from `rows`.
pub hidden_rows: u32,
/// Spans the capture could not record. Non-zero means the trees in here
/// are incomplete and the panel says so.
pub dropped: u32,

pub name: String,
/// Times the span was entered across the whole window, not per frame.
/// The panel divides; the wire carries what was counted.
pub calls: u32,
/// Time in this span with its children's time taken out.
pub self_ns: u64,
/// Time in this span including everything it called.
pub total_ns: u64,
/// The most expensive single entry seen.
pub max_ns: u32,

pub name: String,
/// Times the span was entered across the whole window, not per frame.
/// The panel divides; the wire carries what was counted.
pub calls: u32,
/// Time in this span with its children's time taken out.
pub self_ns: u64,
/// Time in this span including everything it called.
pub total_ns: u64,
/// The most expensive single entry seen.
pub max_ns: u32,

/// Frames folded into this window.
pub frames: u32,
/// Wall time the window covered, in milliseconds.
pub span_ms: f32,
/// The most expensive frame in the window, in pre-order. Empty when the
/// window caught no spans.
pub worst: Vec<Bar>,
/// The instrumented work of that frame, in milliseconds. Its top-level
/// spans added up, which is what the flame chart's bars come to.
pub worst_ms: f32,
/// The wall clock that frame occupied, in milliseconds — the period from
/// one frame to the next, gate and all.
/// 
/// Carried beside the work rather than instead of it, for the reason the
/// Performance panel gives: under the budget the two differ by slack the
/// presentation gate is holding, and a panel showing only one of them
/// cannot tell a cheap frame from a late one.
pub worst_period_ms: f32,
/// Every name seen, most self time first.
pub rows: Vec<Row>,
/// Rows past `MAX_ROWS` that were dropped from `rows`.
pub hidden_rows: u32,
/// Spans the capture could not record. Non-zero means the trees in here
/// are incomplete and the panel says so.
pub dropped: u32,

/// This process — the editor's own chrome, egui and all.
Editor,
/// The child process the editor launched, measured in the child.
Game,

/// The sub-table name. `"display"` becomes `[settings.display]`.
pub name: &'static str,
/// Install a table into the subsystem's global.
/// 
/// `None` means the project named no such table, and the subsystem must
/// install its DEFAULT rather than keep what the last project left. A
/// section that skipped that would leak one project's look into the next.
pub load: fn(Option<&toml::Value>),
/// Merge the subsystem's live values into its own table.
/// 
/// The table is handed over already created. `merge` is what almost every
/// implementation should call, and it is what decides that a value equal
/// to the default is a key that should not exist.
pub save: fn(&mut toml_edit::Table),

/// What passes name this target by. Unique across the graph.
pub name: String,
pub kind: ResourceKind,
/// The texel format. A created colour or aux target must state it, so a
/// write can be checked. An imported target may leave it unset.
pub format: Option<wgpu::TextureFormat>,
/// The MSAA sample count. One for a resolved target.
pub samples: u32,
pub source: ResourceSource,

/// The pass leaves the screen-to-scene map alone.
Identity,
/// The pass warps the frame, so the map needs the pass's own inverse.
Custom,

/// Clear the target to the pass's clear value before drawing.
Clear,
/// Keep what an earlier pass left, and draw over it.
Load,

/// The perf label. Unique across the graph.
pub name: String,
/// The product that owns this pass. The validator rejects a pass whose
/// owner is not among the loaded products.
pub owner: String,
/// Passes this one must follow. Each names a pass in the same graph.
pub after: Vec<String>,
/// Resources this pass samples.
pub inputs: Vec<String>,
/// Colours this pass writes.
pub outputs: Vec<PassOutput>,
/// The depth target this pass writes, if any. It names a depth resource.
pub depth: Option<String>,
/// Resources this pass both reads and writes on purpose. A read-write not
/// listed here is a mistake the validator reports.
pub feedback: Vec<String>,
/// Whether the pass may run when no project is loaded.
pub runs_without_project: bool,
/// Whether the pass is safe to drop when it is off.
pub omit_when_inactive: bool,
