Tool slots, a shared energy pool, and switching.

Call [`Loadout::trigger`] once per frame with the fire button state.

```
use warp_sdk::challenge::{Loadout, Rng, Tool};
use warp_sdk::ultraviolet::Vec2;
let mut l = Loadout::new(100.0, 20.0).with(Tool::dart()).with(Tool::sonic_pulse());
let mut rng = Rng::new(1);
let shot = l.trigger(true, 1.0 / 60.0, Vec2::zero(), Vec2::unit_x(), &mut rng);
assert!(shot.is_some());
l.select(1);
assert_eq!(l.active().name, "sonic pulse");
```

