items.doc:
The threat director: escalation from progress, wave budgets, rests, and
spawns that never appear in view.

```
use warp_sdk::challenge::{Director, DirectorConfig, Profile, Rect, Rng};
use warp_sdk::ultraviolet::Vec2;
let roster = vec![Profile::gloom()];
let mut d = Director::new(DirectorConfig::default());
let mut rng = Rng::new(1);
let view = Rect::centered(Vec2::zero(), Vec2::new(10.0, 6.0));
let acts = d.update(5.0, 0.0, 0, view, &roster, &mut rng);
assert!(!acts.is_empty()); // the first wave started
```

