One chunk as triangles and outline, for the game to draw.

```ignore
for c in terrain.take_dirty_chunks() {
let m = terrain.chunk_mesh(c);
for tri in m.indices.chunks(3) { /* m.vertices[tri[0] as usize] ... */ }
for [a, b] in &m.outline { ctx.draw_line(*a, *b, [220, 200, 160, 255]); }
}
```

