Makes an empty store with no capacity limit.

```
use warp_sdk::economy::Store;
assert_eq!(Store::unlimited("bank").capacity, u32::MAX);
```

Inputs become outputs after a time.

```
use warp_sdk::economy::*;
let r = Recipe::new(
Bundle::new().with(ResourceId(1), 3),
Bundle::new().with(ResourceId(2), 1),
2.0,
);
assert_eq!(r.seconds, 2.0);
```

