use warp_sdk::procgen::{scatter_cluster, Falloff, Rng};
let m = scatter_cluster(&mut Rng::new(0), [0.0, 0.0], 5.0, 10, Falloff::Smooth);
assert!(m.iter().all(|m| m.t <= 1.0 && m.cluster == 0));
```

