A prop rooted on a 2D surface.

```
use warp_sdk::procgen::{place_on_surface, Rooting};
let p = place_on_surface([1.0], |_| (0.0, [0.0, 1.0]), &Rooting::default());
assert_eq!(p[0].angle, 0.0);
```

