 Motion {
/// The length of a one-shot motion, or the period of a loop, in seconds.
pub fn duration(self) -> f32 {
    match self {
        Motion::Still => 0.0,
        Motion::Breathe => 3.2,
        Motion::Pulse => 1.0,
        Motion::SlowPulse => 2.0,
        Motion::Spin => 1.6,
        Motion::Shake => 0.4,
        Motion::Rise | Motion::Fall => 0.8,
        Motion::Flash => 0.25,
    }
}
/// True for a motion that loops.
pub fn loops(self) -> bool {
    matches!(self, Motion::Breathe | Motion::Pulse | Motion::SlowPulse | Motion::Spin)
}
/// The pose at `t` seconds after the state started.
/// 
/// ```ignore
/// let p = Motion::Pulse.pose(0.5);
/// assert!(p.scale > 1.0);
/// ```
pub fn pose(self, t: f32) -> Pose {
    let t = t.max(0.0);
    let d = self.duration();
    let k = if d > 0.0 { (t / d).min(1.0) } else { 1.0 };
    let wave = |p: f32| 0.5 - 0.5 * (TAU * t / p).cos();
    let mut p = Pose::REST;
    match self {
        Motion::Still => {}
        Motion::Breathe => {
            let s = (TAU * t / d).sin();
            p.scale = 1.0 + 0.025 * s;
            p.alpha = 0.925 + 0.075 * s;
        }
        Motion::Pulse => {
            let e = wave(d);
            p.scale = 1.0 + 0.06 * e;
            p.flash = 0.25 * e;
        }
        Motion::SlowPulse => {
            let e = wave(d);
            p.scale = 1.0 + 0.04 * e;
            p.flash = 0.15 * e;
        }
        Motion::Spin => p.arc = Some(TAU * (t / d).fract()),
        Motion::Shake => {
            if k < 1.0 {
                p.dx = 0.05 * (1.0 - k).powi(2) * (TAU * 3.0 * k).sin();
            }
        }
        Motion::Rise => {
            p.dy = -0.35 * (1.0 - (1.0 - k).powi(3));
            p.alpha = 1.0 - k;
        }
        Motion::Fall => {
            p.dy = 0.35 * k * k;
            p.alpha = 1.0 - k;
        }
        Motion::Flash => {
            p.flash = (1.0 - k).powi(2);
            p.scale = 1.0 + 0.04 * (1.0 - k);
        }
    }
    p
}
/// The pose with reduce-motion: rest when `reduce` is true.
pub fn pose_for(self, t: f32, reduce: bool) -> Pose {
    if reduce { Pose::REST } else { self.pose(t) }
}
/// The static mark that shows this state when motion is reduced.
pub fn static_mark(self) -> Mark {
    match self {
        Motion::Pulse | Motion::SlowPulse | Motion::Flash => Mark::DoubleEdge,
        Motion::Spin => Mark::QuarterArc,
        Motion::Rise => Mark::Up,
        Motion::Fall => Mark::Down,
        Motion::Still | Motion::Breathe | Motion::Shake => Mark::None,
    }
}

