GuestLeft { peer: u8, name: String, reason: LeaveReason },
/// The host gave this guest a seat. `rejoined` is true when it is the
/// seat of the rejoin token.
Joined { seat: u8, host_name: String, rejoined: bool },
/// The host went quiet. Reconnect attempts begin.
HostInterrupted,
/// A reconnect attempt started.
Reconnecting { attempt: u32 },
/// The link is back, in the same seat. The application resyncs its
/// state with the host.
Reconnected,
/// The session ended for this guest.
SessionEnded(EndReason),
/// Another person came or went, as a guest sees it (from the roster).
PeerJoined { peer: u8, name: String },
PeerLeft { peer: u8, name: String },
/// A blob transfer moved: bytes received and the packed total.
BlobProgress { name: String, got: u64, total: u64 },
/// A blob arrived and passed its checks: the inflated bytes.
BlobDone { name: String, data: Vec<u8> },
/// A blob failed: too large, short, a bad checksum or a bad inflate.
BlobFailed { name: String, reason: String },
/// Application bytes on `channel`. On the host, `peer` is the seat of
/// the guest that sent it, and the guest filter passed it. On a guest,
/// `peer` is 0: the host sent it.
Message { peer: u8, channel: u16, data: Vec<u8> },

/// The longest handshake, and the longest wait for Welcome on a redial.
pub handshake_timeout: Duration,
/// A link silent for this long is Interrupted (4 s).
pub interrupt_after: Duration,
/// The time in Interrupted before the guest ends with HostLost (60 s).
pub give_up: Duration,
/// The first reconnect wait. The waits are 1, 2, 4, 8, 8, ... x this.
pub backoff_base: Duration,
/// The keepalive period (1 s).
pub keepalive: Duration,

/// The longest handshake and Hello.
pub hello_timeout: Duration,
/// A welcomed guest silent for this long is GuestInterrupted. The
/// default is Timers::interrupt_after (4 s).
pub idle_timeout: Duration,
/// One blob request per guest per this time.
pub blob_period: Duration,
/// How long the seat of an interrupted guest is held (60 s).
pub seat_hold: Duration,
/// The roster keepalive period.
pub keepalive: Duration,
/// True: a guest from a loopback address is not a source for the kick
/// ban and the blob source limit.
pub trust_loopback: bool,
/// The seats, the host included: 2 to MAX_SEATS. The default is 4.
pub max_players: usize,
/// The rate of the application channels that have no limit of their
/// own, shared by those channels.
pub app_limit: ChannelLimit,
/// Application channels with a limit of their own.
pub channel_limits: Vec<(u16, ChannelLimit)>,
/// A guest with more unsent bytes than this does not read. A reliable
/// send to it closes it. It is above BLOB_QUEUE_CAP, so a reliable send
/// right after a blob passes.
pub send_queue_cap: usize,
/// The byte counters of the guest links, and the class of each
/// application channel (mod.rs Counting). The default is fresh
/// counters.
pub counting: Counting,

/// The application name of the handshake. The host must use the same.
pub domain: Domain,
/// This guest's name. The host cleans it.
pub name: String,
/// The build id. A host with another build refuses the guest.
pub build: String,
/// The join code of the host.
pub code: String,
/// How the host is named in the status line until Welcome.
pub label: String,
/// Ask for the seat of this token (a rejoin from a SessionRecord).
pub rejoin: Option<Token>,
/// The transport, for the SessionRecord. With None, the guest makes
/// no record.
pub via: Option<Via>,
pub cfg: GuestConfig,
/// The byte counters of the links of this guest, the first link and
/// each redial, and the class of each application channel (mod.rs
/// Counting). The default is fresh counters.
pub counting: Counting,

/// The guest sent Bye.
Left,
/// The guest stopped answering, and its held seat timed out.
TimedOut,
/// The host kicked the guest.
Kicked,

/// No session.
Off,
/// This process hosts. `interrupted` counts guests whose link went
/// quiet and whose seat is held for their return.
Hosting { guests: usize, interrupted: usize },
/// A guest on its way in: connect, handshake, until the first Welcome.
Joining,
/// A guest with a seat.
Linked,
/// A guest whose host went quiet. `attempt` is the reconnect try in
/// progress, `next_in_s` the wait before the next one, `gives_up_in_s`
/// the time left before the session ends.
Interrupted { attempt: u32, next_in_s: f32, gives_up_in_s: f32 },
/// A guest whose session ended.
Ended(EndReason),

struct Connected {
pub io: FrameIo,
/// Opens a new transport to the same host, for a reconnect.
pub dialer: Option<Dialer>,
/// The transport, for the SessionRecord. None keeps the JoinSpec via.
pub via: Option<Via>,

/// A TCP address, "ip:port" or "name:port".
Tcp(String),
/// The node id of a P2P host. `addr` is a direct address when the
/// join had one (local mode, where no discovery finds the host).
P2p { node: [u8; 32], addr: Option<SocketAddr> },
/// Another transport, named by the application (for example a
/// platform lobby id). One line, no "=" at the start.
Other(String),

/// The invite has no address, or more than two.
AddressCount,
/// The code is not a XXXX-XXXX join code of CODE_ALPHABET.
BadCode,
/// The format tag is empty or not ASCII letters and digits.
BadTag,
/// The text holds no invite with a good check: no tag, a typo, or a
/// cut paste.
NotFound,

/// The tag in front of the symbols, for example "SN". ASCII letters
/// and digits only. A reader finds it at the start of a word, in any
/// case.
pub tag: &'static str,
/// Other prefixes, for example "nova://". A reader finds each one at
/// any position, in any case, so "nova://" also finds "stellanova://".
pub schemes: &'static [&'static str],
/// The port that an invite with no F_PORT flag names.
pub default_port: u16,

/// Read the key from this file (64 hex digits). When the file is
/// missing or bad, make a new key and write it there. Local mode
/// ignores the file and makes a new key (see `uses_key_file`).
File(PathBuf),
/// A new random key: a new node id for each bind.
Fresh,
/// This key. The application keeps it.
Secret([u8; 32]),

pub fn bind(_cfg: P2pConfig) -> Result<P2p, String> { Err(NONE.into()) }
pub fn node_id(&self) -> [u8; 32] { match *self.never {} }
pub fn direct_addr(&self) -> SocketAddr { match *self.never {} }
pub fn is_local(&self) -> bool { match *self.never {} }
pub fn set_accepting(&self, _on: bool) { match *self.never {} }
pub fn accept(&self) -> Option<P2pLink> { match *self.never {} }
pub fn accept_timeout(&self, _t: Duration) -> Result<P2pLink, RecvTimeoutError> { match *self.never {} }
pub fn dial(&self, _node: [u8; 32], _addr: Option<SocketAddr>) -> Result<FrameIo, String> { match *self.never {} }
pub fn status(&self) -> P2pStatus { match *self.never {} }
pub fn path_to(&self, _node: [u8; 32]) -> P2pPath { match *self.never {} }
pub fn close(&self) { match *self.never {} }

/// The QUIC application protocol. Each application has its own, for
/// example b"my-game/link/1". A change of the framing needs a new
/// number. Both peers must use the same ALPN.
pub alpn: Vec<u8>,
pub key: KeySource,
/// Bind 127.0.0.1 with the relay off and no discovery.
pub local: bool,

/// A direct UDP path (after a hole punch, or on a LAN).
Direct,
/// Through a relay, or a relay and a direct path together.
Relay,
/// No path yet, or no connection to that peer.
Connecting,

/// Local mode: 127.0.0.1, no relay, no discovery.
Local,
/// A home relay knows this endpoint, so a guest can find it.
Online,
/// No home relay yet (or no network).
Offline,

/// It went to an open link (or ended that link on bad framing).
Routed,
/// No link is open for that peer.
Unknown,

Ok,
/// The send buffer is full. Try again later.
Full,
/// The peer is gone or the send is refused. The link closes.
Failed(String),

/// The first four bytes of each datagram. Use a tag of the
/// application, so that another application on the LAN is not heard.
pub magic: [u8; 4],
/// The UDP port of the beacon and the listener.
pub port: u16,
/// The build string of this process. Cut to BUILD_CAP bytes.
pub build: String,
/// The wire version of this process.
pub proto: u32,

/// Where to connect: the sender IP and the port it announced.
pub addr: SocketAddr,
pub players: u8,
pub max: u8,
/// False when the host runs another build or wire version.
pub build_ok: bool,
/// The application payload of the beacon, not trusted.
pub payload: Vec<u8>,

/// Frames driven without a panic.
pub frames: u32,
/// The game published at least one census snapshot (Hierarchy/Inspector).
pub census_published: bool,
/// The game published at least one console scrollback.
pub console_published: bool,
/// How many actions the game registered for the Control Map.
pub actions_registered: usize,
/// The most rects, lines, circles and sprites the game recorded in one
/// frame — the peak, not the sum, so a steady game reads as what it draws
/// each frame rather than that times the frame count.
pub shapes_drawn: usize,
/// Whether `scene_underlay` changed a pixel of the HDR target on any
/// checked frame. `None` when no headless device exists.
pub underlay_drew: Option<bool>,
/// The CPU time of each frame in milliseconds: `input`, `render`, `gui`
/// and the underlay encode. One sample for each frame.
pub frame_ms: Vec<f32>,
/// The placeholders that ran, in name order. Empty in a finished game.
pub placeholders: Vec<String>,

items.doc:
What one scripted play saw: the [`Report`] of a boot, and the screens the
game went through. It dereferences to the `Report`.

```ignore
let report = smoke::play::<Game>(Script::new().wait(10).press(Key::Return).wait(30));
assert!(report.path_contains(&["title", "play"]), "{:?}", report.screens());
```

items.body:
/// The boot fields: panels, shapes, underlay, frame times, placeholders.
pub report: Report,
/// The screens from [`report_screen`], in order. A name that repeats on
/// the next frame is kept once.
pub screens: Vec<String>,

items.doc:
Boot `G` and drive `frames` whole frames, with no window and no input.

Panics when a [`placeholder!`](crate::placeholder) ran. To boot an
unfinished game, use `play(Script::new().wait(frames).allow_placeholders())`.

# Example
```ignore
#[test]
fn it_boots() {
let report = warp_sdk::smoke::boot::<Game>(120);
assert!(report.drove_a_panel(), "the game wired no panels");
}
```

Play `G` from `script`, with no window, and report the screens it reached.

Panics when a [`placeholder!`](crate::placeholder) ran, unless the script
calls [`Script::allow_placeholders`].

```ignore
#[test]
fn enter_starts_a_run() {
let report = smoke::play::<Game>(Script::new().wait(10).press(Key::Return).wait(30));
assert!(report.path_contains(&["title", "play"]), "{:?}", report.screens());
}
```

Play `G` from `script`, and call `probe` after each frame with the game
and the frame index from 0. Use the probe to assert that the game state
changed.

```ignore
let mut score = 0;
smoke::play_with::<Game>(script, |game, _frame| score = game.score);
assert!(score > 0, "the script scored nothing");
```

