Beat { frames: u32 },

/// The coach card carries the cue (a key-cap), nothing on the field.
None,
/// A ring over a registered rect (a HUD element or a board cell).
Named(&'static str),

/// Advance when any of these actions has been pressed `times` times.
Press { actions: &'static [&'static str], times: u32 },
