Maximized,
Fullscreen,

pub fxaa_enabled: bool,
pub fxaa_subpix: f32,
pub fxaa_edge_threshold: f32,
pub motion_blur_enabled: bool,
pub motion_blur_intensity: f32,
pub z_dof_enabled: bool,
pub z_dof_aperture: f32,
pub z_dof_max_blur: f32,
pub dof_enabled: bool,
pub dof_aperture: f32,
pub dof_focal_radius: f32,
pub dof_max_blur: f32,
pub pp_enabled: bool,
pub pp_exposure: f32,
/// The bloom switch, under `pp_enabled`. False skips the extract, the
/// four downsample and the four upsample passes, and the composite adds
/// zero bloom. True by default, so a project saved before the switch
/// existed keeps its picture.
pub pp_bloom_enabled: bool,
pub pp_bloom_threshold: f32,
pub pp_bloom_intensity: f32,
pub pp_bloom_radius: f32,
/// The grade switch, under `pp_enabled`. False sends the identity grade
/// (saturation 1, contrast 1, temperature 0, brightness 0) to the
/// tonemap pass and keeps the four values below. True by default, for
/// the same reason as `pp_bloom_enabled`.
pub pp_grade_enabled: bool,
pub pp_saturation: f32,
pub pp_contrast: f32,
pub pp_temperature: f32,
pub pp_brightness: f32,
pub crt_enabled: bool,
pub crt_curvature: f32,
pub crt_corner_radius: f32,
pub crt_scanline_intensity: f32,
pub crt_vignette_intensity: f32,
pub crt_aberration_amount: f32,
pub crt_flicker_intensity: f32,
pub crt_jitter_intensity: f32,
pub crt_hsync_intensity: f32,
pub crt_grain_intensity: f32,
pub crt_grain_size: f32,
pub crt_grain_speed: f32,
pub crt_grain_color: f32,
/// 1.0 is spherical, 0.0 is cylindrical. `curve_y = crt_curvature * this`.
pub crt_curve_aspect: f32,
/// Faceplate thickness, in units of half the screen width.
pub crt_glass_thickness: f32,
/// Refractive index of the faceplate. Soda-lime glass is about 1.52.
pub crt_glass_ior: f32,
/// Mask-to-phosphor spacing, same units as `crt_glass_thickness`.
pub crt_mask_gap: f32,
/// Virtual viewer position, screen widths from centre.
pub crt_eye_x: f32,
pub crt_eye_y: f32,
/// Viewer distance. Larger is more orthographic and flattens the parallax.
pub crt_eye_dist: f32,
/// Master scale on the parallax offset. Zero pins the mask to the image.
pub crt_parallax_strength: f32,
pub crt_conv_r_x: f32,
pub crt_conv_r_y: f32,
pub crt_conv_b_x: f32,
pub crt_conv_b_y: f32,
/// Radial divergence — the bow that grows toward the corners.
pub crt_conv_radial_r: f32,
pub crt_conv_radial_b: f32,
/// 0 none, 1 aperture grille, 2 shadow mask, 3 slot mask, 4 Trinitron.
pub crt_mask_type: u32,
/// Destination pixels per full RGB triad, measured at screen centre.
pub crt_mask_triad_px: f32,
pub crt_mask_strength: f32,
/// Brightness compensation. A mask eats most of the light.
pub crt_mask_boost: f32,
/// Slot mask only: vertical slot period in destination pixels.
pub crt_slot_height_px: f32,
/// Trinitron only: how many damper wires cross the screen.
pub crt_damper_count: f32,
pub crt_damper_strength: f32,
/// How much the mask parallax biases each channel's aperture separately.
pub crt_parallax_coupling: f32,
/// The destination height the three COUNTS below were chosen for, or
/// zero to leave them alone.
/// 
/// WHY A COUNT LOSES ITS DENSITY ON A BIGGER SCREEN. `crt_mask_triad_px`
/// is a pitch in destination pixels, so the continuous mask holds its
/// fineness on any surface. `crt_scanline_count`, `crt_phosphor_triads_x`
/// and `crt_phosphor_rows` are counts across the whole picture, so every
/// feature they describe grows with the surface: a window at twice the
/// height draws the same number of cells at twice the size, which is half
/// the density in pixels, and the mask and the cells stop agreeing.
/// 
/// A project that sets this states the height its counts were tuned at.
/// The three are then multiplied by `output_h / crt_density_ref_h` before
/// they reach the GPU, so the pitch in pixels is what carries across
/// screens and the count is what follows them.
/// 
/// THE HORIZONTAL FOLLOWS THE VERTICAL, and one number is why. A cell
/// keeps its shape on any surface of the reference ASPECT and stretches
/// on any other, which is what a tube fed a signal of the wrong shape
/// does. Two reference numbers would fix the shape and would also let a
/// project set an aspect it never renders at.
/// 
/// Zero is the default and is off, so a project that never heard of this
/// gets the tube it got yesterday at every size.
pub crt_density_ref_h: f32,
/// Lines across the tube. 240 is an arcade signal, 480 a broadcast field.
/// A count, and `crt_density_ref_h` decides whether it holds across
/// surfaces or scales with them.
pub crt_scanline_count: f32,
/// Beam width as a fraction of the line pitch.
pub crt_scanline_thickness: f32,
/// How much a bright beam widens.
pub crt_beam_bloom: f32,
/// True alternates the field every frame.
pub crt_interlace: bool,
/// 0 off, 1 warp grid, 2 displacement, 3 convergence, 4 mask only,
/// 5 magnifier.
pub crt_viz_mode: u32,
/// Loupe centre, in normalized destination coordinates.
pub crt_viz_probe_x: f32,
pub crt_viz_probe_y: f32,
pub crt_viz_zoom: f32,
pub crt_viz_grid_div: f32,
/// False is the shipped state, because the cells are an ADDITIONAL
/// effect. An existing project must get the tube it got yesterday.
pub crt_phosphor_on: bool,
/// How many RGB triads fit across the screen. A COUNT, not a pitch:
/// "how many are there" is the question a person asks, and a pitch in
/// pixels answers it only after a division. `crt_density_ref_h` is what
/// keeps that count from meaning a different pitch on a bigger surface.
pub crt_phosphor_triads_x: f32,
/// How many phosphor rows fit down the screen.
pub crt_phosphor_rows: f32,
/// The black matrix: the fraction of a cell that is the gap around it.
pub crt_phosphor_gap: f32,
/// Beam spot radius, in cells. How many cells the beam averages over.
pub crt_phosphor_beam: f32,
/// Cell shape, 0 rectangular through 1 elliptical.
pub crt_phosphor_round: f32,
/// How much a lit cell spills into the dark matrix around it.
pub crt_phosphor_bleed: f32,
/// How hard a phosphor cell's edge is, 0 analytic through 1 square.
/// 
/// At zero the edge is one destination pixel wide. That width is the
/// correct one, and it is not always the wanted one: a cell at the default
/// density is under three pixels across, so a one-pixel edge is a third of
/// the cell and the grid reads as soft. Toward one the width goes to
/// nothing, which trades aliasing for an edge a person can see.
pub crt_phosphor_sharp: f32,
/// The three emission colours, each as linear RGB.
/// 
/// An array and not nine scalars, because `DEFAULT` has to stay readable
/// and a colour picker takes a `[f32; 3]`. The uniform block holds nine
/// separate `ph_*_*` scalars, and `sync_display_to_gpu` unpacks these
/// into them.
/// 
/// Pure primaries by default: a red cell emits red and nothing else.
/// 
/// A real tube's phosphors are not the primaries — P22 red is an
/// orange-red and P22 green is a yellow-green — and these shipped at
/// those values first. The measured set is the wrong default at the size
/// a cell actually is: the three desaturate each other and the grid reads
/// as a haze rather than as a tube. The measured values remain one drag
/// away for anybody who wants them. The rest of
/// what makes a photographed CRT look like a CRT, so it is a control.
pub crt_ph_r: [f32; 3],
pub crt_ph_g: [f32; 3],
pub crt_ph_b: [f32; 3],
/// DORMANT. Nothing reads it, and no slider drives it.
/// 
/// A partial exemption from the phosphor grid was never a real choice.
/// The grid is a NEIGHBOURHOOD operator — nine taps around a cell centre
/// quantised to the cell — and the exemption was a per-fragment blend, so
/// any value between the ends drew the menu twice: sharp over a combed
/// copy of itself. The chrome has its own render target now and the
/// question is gone with it.
/// 
/// The field is KEPT so a saved settings file keeps round-tripping, and
/// because the uniform block it feeds is a fixed 304 bytes that the
/// Shader Lab reflects one slider per member off.
pub crt_phosphor_gui_exempt: f32,
/// The GUI's share of the raster, the mask and the grain, 0 none through
/// 1 whole. Read by `fs_gui`, which composites the chrome layer over the
/// finished tube.
/// 
/// WHY THE LIST STOPS AT THREE
/// 
/// Only an effect that MULTIPLIES the emitted light can be exempted this
/// way, and these are all of them. The warp, the convergence and the
/// h-sync shift decide WHERE the composite samples; the chrome takes them
/// on purpose, because a menu that stays flat over a picture that bends
/// stops pointing at what it labels. The phosphor cells and the mask
/// parallax are absent for the opposite reason — the chrome never gets
/// them at all.
pub crt_gui_exempt_scan: f32,
pub crt_gui_exempt_mask: f32,
pub crt_gui_exempt_grain: f32,
/// Output gain, spent after the mask and the cells.
pub crt_pic_brightness: f32,
/// Contrast around sRGB mid grey. One leaves the picture alone.
pub crt_pic_contrast: f32,
/// The exponent on the graded picture. Below one lifts the mid tones.
pub crt_pic_gamma: f32,
/// Where the output ceiling starts to compress. One is a hard clamp.
pub crt_pic_knee: f32,
pub lighting_wrap: f32,
pub light_z: f32,

items.doc:
Draw an optional OVERLAY into the HDR scene. The engine encodes it
AFTER the scene pass and before the post-process, so it gets bloom
and CRT. It gets the live encoder, the [hdr_view, z_view] targets, the
primary View (camera) and the window size. Default: no-op.
For a pass that draws BEFORE the scene layers, use `scene_underlay`.

```ignore
fn scene_overlay(&mut self, shared: &SharedGpu, encoder: &mut wgpu::CommandEncoder,
hdr: &wgpu::TextureView, _z: &wgpu::TextureView, view: &View, _px: [u32; 2]) {
self.debug_lines.draw(shared, encoder, hdr, view);
}
```
